#include "../wordcount-cuda/wc.cu"
#include <cuda_runtime.h>
#include <chrono>
#include <fstream>
#include <iostream>
#include <iomanip>
#include <cstdint>
struct Case{std::vector<char>x;char*d;int ref;};
int count_preallocated(char*d,size_t n){if(n==0)return 0;thrust::device_ptr<char> p(d);int wc=thrust::inner_product(p,p+n-1,p+1,0,thrust::plus<int>(),is_word_start());if(is_alpha(static_cast<char>(p[0])))wc++;return wc;}
int main(){std::vector<std::vector<char>>xs(7);xs[1]={65};xs[2]={32};for(int i=91;i<=96;i++){xs[3].push_back(i);xs[3].push_back(32);}for(int i=0;i<256;i++)xs[4].push_back(i);for(int i=0;i<65573;i++)xs[5].push_back((i*73+i/17)%256);int tab[]={0,65,91,32,122,96,127,255,97,0,90};for(int i=0;i<1025;i++)xs[6].push_back(tab[i%11]);std::vector<Case>cases;std::vector<uint32_t>prefix;for(auto&x:xs){Case c;c.x=x;c.ref=word_count_reference(x);cudaMalloc(&c.d,std::max(size_t(1),x.size()));if(!x.empty())cudaMemcpy(c.d,x.data(),x.size(),cudaMemcpyHostToDevice);std::vector<unsigned char>actual(x.size());if(!x.empty())cudaMemcpy(actual.data(),c.d,x.size(),cudaMemcpyDeviceToHost);for(auto q:actual)prefix.push_back(q);prefix.push_back(x.size());prefix.push_back(3);cases.push_back(c);}for(auto&c:cases)count_preallocated(c.d,c.x.size());for(int trial=1;trial<=5;trial++){auto out=prefix;double elapsed=0;bool ok=true;std::cout<<"STUDY_COMPONENT_SECONDS ";for(auto&c:cases){cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();int v=0;for(int rep=0;rep<3;rep++)v=count_preallocated(c.d,c.x.size());cudaDeviceSynchronize();double t=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;elapsed+=t;ok&=v==c.ref;out.push_back(v);std::cout<<std::setprecision(17)<<t<<",";}std::cout<<std::endl;std::string path="trial_"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)out.data(),out.size()*4);f.close();std::cout<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<elapsed<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<out.size()<<",\"max_abs_error\":0,\"timing_region\":\"sum7_three_preallocated_count_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"uint32\",\"count\":"<<out.size()<<",\"byte_order\":\"little\"}}"<<std::endl;if(!ok)return 2;}}
